def colorTreeBipartite(n: int, edges: list[list[int]]) -> list[int]:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * n
    color[0] = 0
    q = deque([0])
    while q:
        curr = q.popleft()
        for nxt in adj[curr]:
            if color[nxt] == -1:
                color[nxt] = 1 - color[curr]
                q.append(nxt)
    return color

